using DevExpress.XtraEditors;
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace Jamera.Employees.Commissions
{
    public partial class Add_Commission : DevExpress.XtraEditors.XtraForm
    {
        public Add_Commission()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill the SqlDataSource asynchronously
            sqlDataSource1.FillAsync();
        }

        private void item_cmb_EditValueChanged(object sender, EventArgs e)
        {

        }

        private void item_cmb_Properties_ButtonClick(object sender, DevExpress.XtraEditors.Controls.ButtonPressedEventArgs e)
        {
            int i = e.Button.Index;

            if (i == 1)
            {
                sqlDataSource1.RebuildResultSchema();
                sqlDataSource1.Fill();
                item_cmb.Refresh();
            }
        }

        public void Save()
        {
            if (item_cmb.Text == "")
            {
                XtraMessageBox.Show("Please select item !");
                item_cmb.ShowPopup();
            }
            else if (am_inp.Text == "")
            {
                XtraMessageBox.Show("Please enter commission for area manager !");
                am_inp.Focus();
            }
            else if (ss_inp.Text == "")
            {
                XtraMessageBox.Show("Please enter commission for senior secretary !");
                ss_inp.Focus();
            }
            else if (js_inp.Text == "")
            {
                XtraMessageBox.Show("Please enter commission for junior secretary !");
                js_inp.Focus();
            }
            else
            {
                Commission_Controller commission_controller = new Commission_Controller();
                bool com_item_exists = commission_controller.Commission_Item_Exists(Convert.ToInt32(item_cmb.EditValue));
                if (com_item_exists == false)
                {
                    Double salesman = 0;
                    if (sm_inp.Text != "")
                    {
                        salesman = Convert.ToDouble(sm_inp.Text);
                    }

                    int com_id = commission_controller.Store(Convert.ToInt32(item_cmb.EditValue), Convert.ToDouble(am_inp.Text), Convert.ToDouble(ss_inp.Text), Convert.ToDouble(js_inp.Text), salesman, desc_inp.Text);
                    if (com_id > 0)
                    {
                        Reset_Entries();
                    }
                }
                else
                {
                    XtraMessageBox.Show("Commission already exists for this item!");
                    item_cmb.Focus();
                }
            }
        }

        public void Reset_Entries()
        {
            item_cmb.Text = null;
            am_inp.Text = null;
            ss_inp.Text = null;
            js_inp.Text = null;
            sm_inp.Text = null;
            desc_inp.Text = null;
            item_cmb.Focus();

        }

        private void save_btn_Click(object sender, EventArgs e)
        {
            this.Save();
        }
    }
}